/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_wishlist_after_delete` AFTER DELETE ON `tbd_users_wishlist_products` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_user`, `record_id`,
         `operation_date`, `table_description`, `operation_status`)
    VALUES
        ('tbd_users_wishlist_products', 'Delete', USER(), OLD.product_ID, NOW(),
         CONCAT('Producto eliminado de lista de deseos. user_ID=', OLD.user_ID,
                ', product_ID=', OLD.product_ID,
                ', status=', IF(OLD.status = b'1', 'Activo', 'Inactivo'),
                ', creation_date=', OLD.creation_date),
         b'1');
END */;;
DELIMITER ;
